bd2920512bde.patch:163: +        self.journal
bd2920512bde.patch:164: +            .stage_pending_action_index_op(&mut self.inner, event)?;
bd2920512bde.patch:165:          // Record the key as staged so a subsequent append_event with
bd2920512bde.patch:166:          // the same `(run, seq)` is rejected by the same-batch
bd2920512bde.patch:167:          // duplicate guard above before the durable lookup.
bd2920512bde.patch:168:          self.staged_event_keys.insert(key);
bd2920512bde.patch:169:          Ok(())
bd2920512bde.patch:170:      }
bd2920512bde.patch:171:  }
