bd2920512bde.patch:1001:      /// PO-009: When commit() returns Err, NO operations from the batch are visible
bd2920512bde.patch:1002:      /// in any keyspace.
bd2920512bde.patch:1003:      ///
bd2920512bde.patch:1004:      /// This test is inherently limited because Fjall's commit() rarely fails in practice.
bd2920512bde.patch:1005:      /// We verify the batch state machine behaves correctly by checking aborted flag
bd2920512bde.patch:1006:      /// and len() invariants after failed encode operations.
bd2920512bde.patch:1007: +    ///
bd2920512bde.patch:1008: +    /// vb-3wn7x: as of this fix, `append_event` for an action-lifecycle
bd2920512bde.patch:1009: +    /// event automatically stages the corresponding `index_action`
bd2920512bde.patch:1010: +    /// mutation in the same batch. A subsequent explicit
bd2920512bde.patch:1011: +    /// `put_action_index` call from the test is therefore redundant —
bd2920512bde.patch:1012: +    /// Fjall last-write-wins leaves the marker in place either way.
bd2920512bde.patch:1013: +    /// The expected `batch.len()` after `append_event` of an
bd2920512bde.patch:1014: +    /// `ActionScheduled` plus an explicit `put_action_index` is now 3:
bd2920512bde.patch:1015: +    /// one for the event, one auto-staged by `append_event`, and one
bd2920512bde.patch:1016: +    /// from the explicit call.
bd2920512bde.patch:1017:      #[test]
bd2920512bde.patch:1018:      fn test_batch_commit_all_or_nothing_across_keyspaces(
bd2920512bde.patch:1019:          action_val in 1u16..=100u16,
bd2920512bde.patch:1020:          run_val in 1u64..=1000u64,
bd2920512bde.patch:1021:          step_val in 0u16..=50u16,
bd2920512bde.patch:1022:      ) {
bd2920512bde.patch:1023:          let action = ActionId::new(action_val);
