dec0e41e2690.patch:468: +    ///
dec0e41e2690.patch:469: +    /// Reads the current counter from the `system` keyspace, increments it,
dec0e41e2690.patch:470: +    /// and writes back the new value in a single batch commit. The caller's
dec0e41e2690.patch:471: +    /// write_lock serializes concurrent callers so that two callers never
dec0e41e2690.patch:472: +    /// observe the same counter value.
dec0e41e2690.patch:473: +    ///
dec0e41e2690.patch:474: +    /// Returns `JournalError::SequenceOverflow` when the counter is already
dec0e41e2690.patch:475: +    /// at `EventSeq::MAX` — no wrapping or silent reuse.
dec0e41e2690.patch:476: +    pub fn accept_seq_allocate(&self) -> Result<EventSeq, JournalError> {
dec0e41e2690.patch:477: +        let _guard = self
dec0e41e2690.patch:478: +            .write_lock
dec0e41e2690.patch:479: +            .lock()
dec0e41e2690.patch:480: +            .map_err(|_| JournalError::WriteLockPoisoned)?;
dec0e41e2690.patch:481: +        let current: u64 = self
dec0e41e2690.patch:482: +            .system
dec0e41e2690.patch:483: +            .get(SYSTEM_ACCEPT_SEQ_KEY)?
dec0e41e2690.patch:484: +            .map(|raw| -> Result<u64, JournalError> {
dec0e41e2690.patch:485: +                let buf: [u8; 8] = raw
dec0e41e2690.patch:486: +                    .as_ref()
dec0e41e2690.patch:487: +                    .try_into()
dec0e41e2690.patch:488: +                    .map_err(|_| JournalError::KeyCapacity)?;
dec0e41e2690.patch:489: +                Ok(u64::from_be_bytes(buf))
dec0e41e2690.patch:490: +            })
dec0e41e2690.patch:491: +            .transpose()?
dec0e41e2690.patch:492: +            .unwrap_or(0);
dec0e41e2690.patch:493: +        let next = current
dec0e41e2690.patch:494: +            .checked_add(1)
dec0e41e2690.patch:495: +            .ok_or(JournalError::SequenceOverflow)?;
dec0e41e2690.patch:496: +        let mut batch = self.database.batch();
dec0e41e2690.patch:497: +        batch.insert(
dec0e41e2690.patch:498: +            &self.system,
dec0e41e2690.patch:499: +            SYSTEM_ACCEPT_SEQ_KEY,
dec0e41e2690.patch:500: +            next.to_be_bytes().as_slice(),
dec0e41e2690.patch:501: +        );
dec0e41e2690.patch:502: +        batch.commit()?;
