bd2920512bde.patch:45: +    Insert {
bd2920512bde.patch:46: +        action: ActionId,
bd2920512bde.patch:47: +        run: RunId,
bd2920512bde.patch:48: +        step: StepIdx,
bd2920512bde.patch:49: +    },
bd2920512bde.patch:50: +    /// Tombstone the marker at `(action, run, step)`.
bd2920512bde.patch:51: +    Remove {
bd2920512bde.patch:52: +        action: ActionId,
bd2920512bde.patch:53: +        run: RunId,
bd2920512bde.patch:54: +        step: StepIdx,
bd2920512bde.patch:55: +    },
bd2920512bde.patch:56: +}
bd2920512bde.patch:57: +
bd2920512bde.patch:58: +/// Classifies a journal event into the pending-action-index mutation it
bd2920512bde.patch:59: +/// implies (if any). Returns `None` for events that leave the index
bd2920512bde.patch:60: +/// untouched.
bd2920512bde.patch:61: +fn pending_action_index_op_for(event: &JournalEvent) -> Option<PendingActionIndexOp> {
bd2920512bde.patch:62: +    match event {
bd2920512bde.patch:63: +        // Insert-side — pending actions enter the index.
bd2920512bde.patch:64: +        JournalEvent::ActionScheduled {
bd2920512bde.patch:65: +            action, run, step, ..
bd2920512bde.patch:66: +        } => Some(PendingActionIndexOp::Insert {
bd2920512bde.patch:67: +            action: *action,
bd2920512bde.patch:68: +            run: *run,
bd2920512bde.patch:69: +            step: *step,
bd2920512bde.patch:70: +        }),
bd2920512bde.patch:71: +        JournalEvent::ActionScheduledTicket { ticket, .. } => Some(PendingActionIndexOp::Insert {
bd2920512bde.patch:72: +            action: ticket.action,
bd2920512bde.patch:73: +            run: ticket.run,
bd2920512bde.patch:74: +            step: ticket.step,
bd2920512bde.patch:75: +        }),
bd2920512bde.patch:76: +        // Remove-side — terminal actions leave the index.
bd2920512bde.patch:77: +        JournalEvent::ActionCompletedEvent {
bd2920512bde.patch:78: +            action, run, step, ..
bd2920512bde.patch:79: +        }
bd2920512bde.patch:80: +        | JournalEvent::ActionFailedEvent {
bd2920512bde.patch:81: +            action, run, step, ..
bd2920512bde.patch:82: +        } => Some(PendingActionIndexOp::Remove {
bd2920512bde.patch:83: +            action: *action,
bd2920512bde.patch:84: +            run: *run,
bd2920512bde.patch:85: +            step: *step,
bd2920512bde.patch:86: +        }),
bd2920512bde.patch:87: +        JournalEvent::ActionCompletedEnvelope { ticket, .. }
bd2920512bde.patch:88: +        | JournalEvent::ActionAbandoned { ticket, .. } => Some(PendingActionIndexOp::Remove {
bd2920512bde.patch:89: +            action: ticket.action,
bd2920512bde.patch:90: +            run: ticket.run,
bd2920512bde.patch:91: +            step: ticket.step,
bd2920512bde.patch:92: +        }),
bd2920512bde.patch:93: +        // Everything else is a no-op for the index.
bd2920512bde.patch:94: +        _ => None,
bd2920512bde.patch:95: +    }
bd2920512bde.patch:96: +}
bd2920512bde.patch:97: +
bd2920512bde.patch:98: +impl FjallJournal {
bd2920512bde.patch:99: +    /// Stages the pending-action-index mutation implied by `event` onto
bd2920512bde.patch:100: +    /// the supplied `fjall::OwnedWriteBatch`.
bd2920512bde.patch:101: +    ///
bd2920512bde.patch:102: +    /// Callers MUST commit the same batch that stages the corresponding
bd2920512bde.patch:103: +    /// `JournalEvent` write so the index update is atomic with the event.
bd2920512bde.patch:104: +    /// Events that imply no index change are silently accepted (the
bd2920512bde.patch:105: +    /// helper returns `Ok(())` without staging any batch operation).
bd2920512bde.patch:106: +    ///
bd2920512bde.patch:107: +    /// # Errors
bd2920512bde.patch:108: +    ///
bd2920512bde.patch:109: +    /// Returns `JournalError::KeyCapacity` if the encoded
bd2920512bde.patch:110: +    /// `index_action` key would overflow the 13-byte fixed-length
bd2920512bde.patch:111: +    /// contract.
bd2920512bde.patch:112: +    pub(crate) fn stage_pending_action_index_op(
bd2920512bde.patch:113: +        &self,
bd2920512bde.patch:114: +        batch: &mut fjall::OwnedWriteBatch,
bd2920512bde.patch:115: +        event: &JournalEvent,
bd2920512bde.patch:116: +    ) -> Result<(), JournalError> {
bd2920512bde.patch:117: +        let Some(op) = pending_action_index_op_for(event) else {
bd2920512bde.patch:118: +            return Ok(());
bd2920512bde.patch:119: +        };
bd2920512bde.patch:120: +        match op {
bd2920512bde.patch:121: +            PendingActionIndexOp::Insert { action, run, step } => {
bd2920512bde.patch:122: +                let key = index_action_key(action, run, step)?;
bd2920512bde.patch:123: +                batch.insert(&self.index_action, key, Vec::<u8>::new());
bd2920512bde.patch:124: +                Ok(())
bd2920512bde.patch:125: +            }
bd2920512bde.patch:126: +            PendingActionIndexOp::Remove { action, run, step } => {
bd2920512bde.patch:127: +                let key = index_action_key(action, run, step)?;
bd2920512bde.patch:128: +                batch.remove(&self.index_action, key);
bd2920512bde.patch:129: +                Ok(())
bd2920512bde.patch:130: +            }
bd2920512bde.patch:131: +        }
bd2920512bde.patch:132: +    }
bd2920512bde.patch:133: +}
